import {clamp,dist,angleDelta,seeded} from './touch-utils.js';
export const DENTAL_TOOLS=[{id:'brush',name:'Brush',icon:'🪥',hint:'Scrub the dirty patch back and forth.'},{id:'water',name:'Water',icon:'💦',hint:'Hold on plaque to spray it clean.'},{id:'pick',name:'Pick',icon:'🪝',hint:'Trace a ring around trapped food or candy.'},{id:'fill',name:'Filling',icon:'🧴',hint:'Hold inside the purple cavity.'},{id:'pull',name:'Extractor',icon:'🔧',hint:'Grip the loose tooth, then pull along its arrow.'},{id:'polish',name:'Polish',icon:'✨',hint:'Rub across the dull tooth to make it shine.'},{id:'replace',name:'New tooth',icon:'🦷',hint:'Drag a tooth from the tray into the gap. Match its angle.'},{id:'align',name:'Align',icon:'↻',hint:'Drag around the crooked tooth to straighten it.'}];
export const PATIENTS=[{name:'Bucky Stardust',color:'#8d8be8',kind:'buck',mood:'A champion carrot cruncher.'},{name:'Tri-Rex',color:'#70cbb8',kind:'triple',mood:'Three rows. One enormous grin.'},{name:'Gloop',color:'#7dd780',kind:'slime',mood:'Floating teeth need a gentle touch.'},{name:'Count Giggles',color:'#bc8cdb',kind:'vampire',mood:'Those fangs are for jelly sandwiches.'},{name:'Fluff Puff',color:'#f2abca',kind:'fluffy',mood:'Ticklish cheeks. Tiny teeth.'},{name:'Ember',color:'#eeaf73',kind:'dragon',mood:'Only breathes confetti.'},{name:'Wink',color:'#6fbae3',kind:'cyclops',mood:'One eye on the candy cupboard.'}];
const kinds=['dirt','plaque','food','cavity','loose','polish','missing','candy','crooked'];
export class DentistModel{
 constructor({level=1,difficulty=3}={}){this.levelId=level;this.difficulty=difficulty;this.patient={...PATIENTS[(level-1)%7]};this.rng=seeded(level*311+difficulty*999);this.clock=0;this.duration=[210000,195000,180000,170000,160000][difficulty-1];this.teeth=[];this.pointers=new Map();this.tool='brush';this.replacementAngle=0;this.correct=0;this.mistakes=0;this.finishedAt=null;this.complete=false;this.done=false;this.events=[];this.feedback=DENTAL_TOOLS[0].hint;this.lastError=-1000;
 const n=[6,8,12,14,18][difficulty-1],rows=this.patient.kind==='triple'?3:2,per=Math.ceil(n/rows),scale=[1.2,1.1,1,.94,.85][difficulty-1];
 for(let i=0;i<n;i++){const row=Math.floor(i/per),col=i%per,span=Math.min(650,per*90),x=500-span/2+(col+.5)*span/per,y=240+row*(rows===3?105:145),available=difficulty===1?['dirt','food','polish']:difficulty===2?kinds.slice(0,6):kinds;const task=available[(i+level-1)%available.length],second=difficulty>=4&&i%4===0?task==='dirt'?'polish':'dirt':null;this.teeth.push({id:i,x,y,w:(this.patient.kind==='fluffy'?42:56)*scale,h:(this.patient.kind==='buck'&&i<2?88:this.patient.kind==='vampire'&&(col===0||col===per-1)?98:70)*scale,angle:task==='crooked'?.4:0,slotAngle:task==='missing'&&difficulty>=3?(i%3-1)*Math.PI/12:0,tasks:[task,...(second?[second]:[])],progress:{},sectors:new Set(),pullDirection:i%2?1:-1,completed:new Set()});}
 this.total=this.teeth.reduce((s,t)=>s+t.tasks.length,0);this.treated=0;this.bursts=[];}
 get reaction(){const phase=this.clock%[12000,10500,9000,8200,7400][this.difficulty-1];return phase>6800&&phase<7250?'sneeze':phase>6200&&phase<=6800?'warning':phase>4500&&phase<5100?'giggle':'smile';}
 toothPosition(t){const moving=this.difficulty>=3,amp=moving?(this.difficulty-1)*3:0;return{x:t.x+Math.sin(this.clock/900+t.id*.1)*amp,y:t.y+Math.cos(this.clock/1100)*amp*.5+(this.patient.kind==='slime'?Math.sin(this.clock/600+t.id)*6:0)};}
 tongue(){return{x:500+Math.sin(this.clock/1100)*[0,0,80,150,200][this.difficulty-1],y:415+Math.sin(this.clock/1500)*28,w:100,h:35};}
 active(t,kind){return t.tasks.includes(kind)&&!t.completed.has(kind);}
 problemAt(x,y){return this.teeth.find(t=>{const p=this.toothPosition(t);return Math.abs(x-p.x)<t.w*.65&&Math.abs(y-p.y)<t.h*.65;});}
 error(message){if(this.clock-this.lastError<450)return;this.mistakes++;this.lastError=this.clock;this.feedback=message;this.events.push('oops');}
 input(kind,x,y,id){if(this.done)return false;if(kind==='down'){if(this.pointers.has(id)||this.pointers.size>=2)return false;const tooth=this.problemAt(x,y);this.pointers.set(id,{id,tool:this.tool,x,y,prev:{x,y},start:{x,y},at:this.clock,tooth:tooth?.id,trace:new Set(),valid:0,travel:0});return true;}
 const p=this.pointers.get(id);if(!p)return false;if(kind==='move'){p.travel+=Math.hypot(x-p.x,y-p.y);p.prev={x:p.x,y:p.y};p.x=x;p.y=y;this.apply(p,Math.min(25,this.clock-(p.lastApply??this.clock)),true);return true;}
 if(kind==='up'){p.prev={x:p.x,y:p.y};p.x=x;p.y=y;this.finishGesture(p);this.pointers.delete(id);return true;}if(kind==='cancel'){this.pointers.delete(id);return true;}return false;}
 finishTask(t,kind){if(!this.active(t,kind))return;t.completed.add(kind);t.progress[kind]=1;this.treated++;this.correct++;this.events.push('sparkle');this.bursts.push({...this.toothPosition(t),born:this.clock});this.feedback=kind==='loose'?'Pop! A tiny tooth fairy catches it.':'Beautiful! '+this.treated+' / '+this.total+' treatments complete.';if(this.treated===this.total){this.complete=true;this.done=true;this.finishedAt=this.clock;this.events.push('finish');}}
 apply(p,dt,moving=false){p.lastApply=this.clock;const t=this.problemAt(p.x,p.y),target=t&&this.toothPosition(t);if(this.difficulty>=4&&Math.abs(p.x-this.tongue().x)<48&&Math.abs(p.y-this.tongue().y)<20){this.feedback='Tongue wiggle! Wait for a clear spot.';return;}
 const map={brush:'dirt',water:'plaque',pick:t&&this.active(t,'candy')?'candy':'food',fill:'cavity',pull:'loose',polish:'polish',replace:'missing',align:'crooked'},kind=map[p.tool];if(t?.completed.has(kind))return;if(!t||!this.active(t,kind)){if(moving&&p.travel>15&&!['replace','pull','align'].includes(p.tool))this.error('Try the tool shown on this tooth’s checklist.');return;}
 const motion=dist(p,p.prev);if(p.tool==='brush'||p.tool==='polish'){if(!moving||motion<1||motion>100)return;const gain=motion/([260,300,340,380,420][this.difficulty-1]);t.progress[kind]=clamp((t.progress[kind]||0)+gain,0,1);p.prev={x:p.x,y:p.y};if(t.progress[kind]>=1)this.finishTask(t,kind);}
 if(p.tool==='water'){t.progress[kind]=clamp((t.progress[kind]||0)+dt/[800,1000,1150,1300,1450][this.difficulty-1],0,1);if(t.progress[kind]>=1)this.finishTask(t,kind);}
 if(p.tool==='fill'){const radius=[23,21,18,16,14][this.difficulty-1];if(dist(p,target)>radius){if(moving)this.error('Keep the filling inside the purple cavity.');return;}t.progress[kind]=clamp((t.progress[kind]||0)+dt/1100,0,1);if(t.progress[kind]>=1)this.finishTask(t,kind);}
 if(p.tool==='pick'&&moving){const r=dist(p,target),radius=t.w*.28;if(r<radius*.6||r>radius*1.7){this.error('Trace the dotted ring gently.');return;}const a=Math.atan2(p.y-target.y,p.x-target.x);t.sectors.add(Math.floor((a+Math.PI)/Math.PI*6)%12);t.progress[kind]=t.sectors.size/10;if(t.sectors.size>=10)this.finishTask(t,kind);}
 }
 finishGesture(p){const t=this.teeth[p.tooth],target=t&&this.toothPosition(t);if(p.tool==='pull'&&t&&this.active(t,'loose')){const dx=p.x-p.start.x,dy=p.y-p.start.y,elapsed=this.clock-p.at,speed=Math.hypot(dx,dy)/Math.max(.05,elapsed/1000);if(dy*t.pullDirection>40&&Math.abs(dx)<24&&elapsed>180&&speed<900)this.finishTask(t,'loose');else this.error('Pull steadily along the tooth’s arrow.');}
 if(p.tool==='replace'){const slot=this.problemAt(p.x,p.y);if(slot&&this.active(slot,'missing')&&dist(p,this.toothPosition(slot))<22&&Math.abs(angleDelta(this.replacementAngle,slot.slotAngle))<=Math.PI/12+.01&&p.start.y>525){this.finishTask(slot,'missing');}else this.error('Drag from the new-tooth tray and align its angle with the gap.');}
 if(p.tool==='align'&&t&&this.active(t,'crooked')){const angle=Math.atan2(p.y-target.y,p.x-target.x)+Math.PI/2;if(Math.abs(angleDelta(angle,0))<.25&&p.travel>22){t.angle=0;this.finishTask(t,'crooked');}else this.error('Slide around the tooth until it points straight up.');}}
 update(dt){if(this.done)return;this.clock+=dt;this.bursts=this.bursts.filter(b=>this.clock-b.born<900);for(const p of this.pointers.values())this.apply(p,dt);if(this.clock>=this.duration){this.done=true;this.feedback='Clinic break! Your monster is still smiling.';}}
 cancel(){this.pointers.clear();}
 get accuracy(){return Math.round(100*this.treated/Math.max(1,this.treated+this.mistakes));}
 get stars(){return this.complete?1+(this.accuracy>=90?1:0)+(this.mistakes===0?1:0):0;}
 get score(){return Math.max(0,this.treated*90+(this.complete?500+Math.max(0,Math.floor((this.duration-this.clock)/250)):0)-this.mistakes*25);}
 summary(){return{completed:this.complete,treated:this.treated,total:this.total,mistakes:this.mistakes,perfect:this.complete&&this.mistakes===0,patient:this.patient.name,stars:this.stars};}
}
export function compareDentist(a,b){if(a.complete!==b.complete)return a.complete?1:-1;const coverage=a.treated/a.total-b.treated/b.total;if(!a.complete&&coverage)return coverage;const accuracy=a.accuracy-b.accuracy;if(accuracy)return accuracy;return (b.finishedAt??b.clock)-(a.finishedAt??a.clock);}
